exercises.statement:
Base vide. Créez une table `fournisseurs` avec :
- `id` : entier, clé primaire ;
- `nom` : texte obligatoire ;
- `pays` : texte, valant `'France'` par défaut ;

puis insérez deux fournisseurs : `(1, 'Clavitech')` (pays par défaut) et `(2, 'Audiolux', 'Belgique')`.

exercises.starter:
CREATE TABLE fournisseurs (
  id INTEGER PRIMARY KEY
);

exercises.solution:
CREATE TABLE fournisseurs (
  id INTEGER PRIMARY KEY,
  nom TEXT NOT NULL,
  pays TEXT DEFAULT 'France'
);
INSERT INTO fournisseurs (id, nom) VALUES (1, 'Clavitech');
INSERT INTO fournisseurs (id, nom, pays) VALUES (2, 'Audiolux', 'Belgique');

UPDATE produits
SET prix = ROUND(prix * 1.05, 2)
WHERE categorie = 'Audio';

exercises.starter:
SELECT nom, prix
FROM produits
WHERE prix > 100;

exercises.solution:
SELECT nom, prix
FROM produits
WHERE prix > (SELECT AVG(prix) FROM produits);

